#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * rule_key: gov-default-all-threads-c273
 * rule_statement: 治理运行前必须填充 post_mortem 结构化分析
 * trae_event: Stop
 * matcher: (无 matcher，Stop 事件触发)
 *
 * 场景发散设计结论：
 *   触发场景：会话停止时，检查是否有未完成的治理任务
 *   跳过场景：简单问答、无代码修改的会话
 *   边界情况：无 .trae/gates/ 目录 → PASS
 *   检查逻辑：检查最近是否有代码修改但未运行治理
 *   失败建议：运行 memory-governance-run skill 或手动触发治理
 */

import fs from "fs";
import path from "path";
import { runHook, getCwd } from "./_lib.mjs";

function shouldRun(context) {
  // Stop 事件总是触发检查
  return true;
}

function run(context) {
  const cwd = getCwd(context);
  const gatesDir = path.join(cwd, ".trae", "gates");

  // 无 gates 目录，跳过
  if (!fs.existsSync(gatesDir)) {
    return { action: "PASS" };
  }

  // 检查最近 10 分钟内是否有代码修改
  const srcDirs = ["services", "src", "lib"].map(d => path.join(cwd, d));
  const now = Date.now();
  const tenMinAgo = now - 10 * 60 * 1000;
  let hasRecentEdit = false;

  for (const dir of srcDirs) {
    if (!fs.existsSync(dir)) continue;
    try {
      const entries = fs.readdirSync(dir, { withFileTypes: true, recursive: false });
      for (const entry of entries) {
        if (!entry.isFile()) continue;
        const fullPath = path.join(dir, entry.name);
        const stat = fs.statSync(fullPath);
        if (stat.mtimeMs > tenMinAgo) {
          hasRecentEdit = true;
          break;
        }
      }
    } catch {
      // 忽略读取错误
    }
    if (hasRecentEdit) break;
  }

  if (hasRecentEdit) {
    return {
      action: "WARN",
      reason: "检测到最近 10 分钟内有代码修改，但未运行治理。建议在会话结束前运行治理以沉淀知识。",
      suggestions: [
        "运行 memory-governance-run skill 执行治理",
        "或手动调用 memory_ingest_candidate 沉淀关键决策",
        "如本次修改无需沉淀，可忽略此提醒"
      ]
    };
  }

  return { action: "PASS" };
}

runHook(shouldRun, run, "Stop");
